def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid row of 2s is the wall objects settle against.
    wall_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    wall = wall_rows[0] if wall_rows else (h - 1)
    toward_top = wall == 0

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or grid[r][c] == 2 or (r, c) in seen:
                continue
            color = grid[r][c]
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    objects.sort(
        key=lambda obj: min(r for r, _ in obj[1]) if toward_top
        else -max(r for r, _ in obj[1])
    )

    out = [[0] * w for _ in range(h)]
    for r in wall_rows:
        for c in range(w):
            out[r][c] = 2
    if not wall_rows:
        for c in range(w):
            out[h - 1][c] = 2

    for color, cells in objects:
        dr = -1 if toward_top else 1
        shift = 0
        while True:
            next_cells = [(r + shift + dr, c) for r, c in cells]
            if any(r < 0 or r >= h or out[r][c] != 0 for r, c in next_cells):
                break
            shift += dr
        for r, c in cells:
            out[r + shift][c] = color

    return out
